class Solution:
    def findRightInterval(self, intervals):
        n = len(intervals)
        res = [-1] * n
        for i in range(n):
            best, bs = -1, float('inf')
            for j in range(n):
                s = intervals[j][0]
                if s >= intervals[i][1] and s < bs:
                    bs, best = s, j
            res[i] = best
        return res

