import bisect

class Solution:
    def findRightInterval(self, intervals):
        pairs = sorted((s, i) for i, (s, e) in enumerate(intervals))
        starts = [p[0] for p in pairs]
        res = []
        for _, e in intervals:
            k = bisect.bisect_left(starts, e)
            res.append(pairs[k][1] if k < len(starts) else -1)
        return res

