        for (int i = 0; i < n; i++) starts[i] = pairs[i].first;
        vector<int> res(n);
        for (int i = 0; i < n; i++) {
            int k = lower_bound(starts.begin(), starts.end(), intervals[i][1]) - starts.begin();
            res[i] = k < n ? pairs[k].second : -1;
        }
