class Solution {
    public int[] findRightInterval(int[][] intervals) {
        int n = intervals.length;
        int[][] pairs = new int[n][2];
        for (int i = 0; i < n; i++) { pairs[i][0] = intervals[i][0]; pairs[i][1] = i; }
        Arrays.sort(pairs, (a, b) -> Integer.compare(a[0], b[0]));
        int[] starts = new int[n];
        for (int i = 0; i < n; i++) starts[i] = pairs[i][0];
        int[] res = new int[n];
        for (int i = 0; i < n; i++) {
            int k = Arrays.binarySearch(starts, intervals[i][1]);
            if (k < 0) k = -(k + 1);
            res[i] = k < n ? pairs[k][1] : -1;
        }
        return res;
    }
}

