var findRightInterval = function(intervals) {
    const n = intervals.length;
    const pairs = intervals.map((iv, i) => [iv[0], i]).sort((a, b) => a[0] - b[0]);
    const starts = pairs.map(p => p[0]);
    const res = [];
    for (const [, e] of intervals) {
        let lo = 0, hi = n;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (starts[mid] < e) lo = mid + 1; else hi = mid;
        }
        res.push(lo < n ? pairs[lo][1] : -1);
    }
    return res;
};
